"""Rewrite docs/space-budget.md from the fit model."""
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from mechanical.band_mech import stack as S          # noqa: E402
from mechanical.band_mech.checks import full_report  # noqa: E402

rep = full_report()
o = ["# Space budget", "",
     "Generated by `tools/space_budget.py` from the model in `mechanical/`. Lengths in millimetres.",
     "Part sizes come from `parts/parts.yaml`; several are still unverified there, and the cells",
     "are trade size codes with estimated capacities, not a supplier's drawing.", "",
     "## Rules the model applies", "",
     "- From the wrist outwards: back wall, adhesive, cell, gap, board, parts, gap, front wall.",
     f"- Cell: {S.SWELL:.0%} thickness growth allowed for; {S.CELL_GAP} around it; {S.CELL_TABS} beyond its body for the tabs;",
     f"  {S.BOARD_CLEAR} between the swollen cell and the board.",
     "- The microphones are bottom-port parts: they hang under the board, one at each end, with their hole",
     "  through it. The cell stops short of both ends, and the same two zones hold the spring contacts.",
     f"- The two microphones are at least {S.MIN_MIC_DISTANCE:.0f} apart.",
     "- Every large part has a place on the board and none overlaps another or a keep-out (antenna corner,",
     "  button cap, microphone gaskets, cell tab slot). The fine-pitch chips keep "
     f"{S.FINE_PITCH_MARGIN} clear around them.",
     f"- Small parts are counted by area, each with {S.PART_SPACING} of spacing, and may take at most {S.PACKING:.0%} of the",
     "  free board. This checks that the parts have room; it does not check that the tracks can be routed.", ""]
for key, e in rep["envelopes"].items():
    adopted = " (adopted)" if key == rep["adopted"] else ""
    o += [f"## Envelope {e['envelope']}{adopted}: {e['pod'][0]} x {e['pod'][1]} x {e['pod'][2]}", "",
          f"**Result: {'everything fits' if e['ok'] else 'does not fit: ' + '; '.join(e['problems'])}.**", "",
          "| Layer | Thickness |", "| --- | --- |"]
    o += [f"| {k} | {v} |" for k, v in e["stack"].items()]
    c, r, a, m = e["cell"], e["cell_room"], e["area"], e["mass"]
    o += ["", f"- **Room for the cell**: {r['length']} x {r['width']} x {r['thickness']} (thickness before swelling)."]
    if c:
        o += [f"- **Cell**: {c['mpn']}, {c['size'][0]} x {c['size'][1]} x {c['size'][2]}, about {c['capacity_mah']} mAh. "
              f"Spare: {c['spare_length']} in length, {c['spare_width']} in width, {c['spare_height']} in height.",
              f"- **Under the board**: {c['board_to_back_wall']} to the back wall, which is the height the spring contacts must span."]
    o += [f"- **Board**: {e['board'][0]} x {e['board'][1]}, {a['board']} mm2. Large parts and keep-outs take {a['large_parts_and_keepouts']}; "
          f"the {a['small_parts']} small parts need {a['small_parts_need']}, {a['share_of_free']:.0%} of what is free.",
          f"- **Microphones**: {e['mic_distance']} apart.",
          f"- **Mass** (estimate): shell {m['shell_g']} g, board {m['board_g']} g, cell {m['cell_g']} g, about {m['total_g_estimate']} g without strap.",
          f"- Drawings: [board from outside](../mechanical/out/plan-{key}.svg), [section](../mechanical/out/section-{key}.svg).", ""]
o += ["## What a larger pod buys", "",
      f"Pod {rep['envelopes']['A']['pod'][0]} long, as envelope A. The cell is the best in `parts/parts.yaml` that fits.", "",
      "| Width | Height | Room for the cell | Best cell | Capacity |", "| --- | --- | --- | --- | --- |"]
for row in rep["size_sweep"]:
    r = row["room"]
    o.append(f"| {row['pod'][1]} | {row['pod'][2]} | {r['length']} x {r['width']} x {r['thickness']} | "
             f"{row['best_cell'] or 'none'} | {str(row['capacity_mah']) + ' mAh' if row['best_cell'] else ''} |")
o += ["", "Length adds room one for one: each millimetre of pod is a millimetre of cell, about 5 mAh at this",
      "width and thickness. The list has no cell longer than 25 that is narrow enough, so the table does not show it.", ""]
(ROOT / "docs" / "space-budget.md").write_text("\n".join(o))
print("docs/space-budget.md written")
